    "content": "8月24日晚，向佐发文称，不想再公开提家事，并发文“这是逼我营业吗”。 是的，谁愿意来回拿家里的事情，公开说呢！而且还是个公众人物了。 01、向太是个好妈妈 （1）上一次向佐被易立竞的采访，大家对向佐的口碑直接180度大转弯，向佐原来是这样的正面、励志、温暖等的一个人了。 其实，他一直是这样一个积极向上的一个人，只是有的人，就把他给黑化了。 即使是这样，他没有出来澄清一次，可想而知他的内心又有多么的强大呀！ 像他的老婆郭碧婷说的那样，“我喜欢被误会，别人误会我我会很开心，你最好一辈子误会我，这样我才能更自由的生活”…"
