    "description": "网站是https://stock-island.com/ 做这个 App 的原因其实挺简单的。 我平时工作的时候，偶尔会想快速看一眼自己关注的股票。以前一般是掏出手机看，或者打开同花顺、券商客户端之类的 App 。 但为了确认一个价格，专门拿出手机有点打断工作。电脑上的券商客户端功能又比较重，打开后整个界面都是行情和交易内容，旁边的同事一眼就能看出来你正在关注股票。 所以我当时想，能不能做一个存在感低一点的行情工具：平时不用打开完整窗口…",
    "content": "网站是 https://stock-island.com/ 做这个 App 的原因其实挺简单的。 我平时工作的时候，偶尔会想快速看一眼自己关注的股票。以前一般是掏出手机看，或者打开同花顺、券商客户端之类的 App 。 但为了确认一个价格，专门拿出手机有点打断工作。电脑上的券商客户端功能又比较重，打开后整个界面都是行情和交易内容，旁边的同事一眼就能看出来你正在关注股票。 所以我当时想，能不能做一个存在感低一点的行情工具：平时不用打开完整窗口，需要的时候只看一眼，看完继续工作。 一开始也考虑过放在菜单栏里，不过我的菜单…"
