    "content": "北京时间8月28日晚，2026年美国网球公开赛资格赛继续进行，在决胜轮的一场比赛中，中国选手郑钦文2-1击败普里丹金娜，连赢三场成功突围，锁定正赛门票。 由于雨水影响，本场比赛延后至28日进行。在此前一日的比赛中，郑钦文首盘6-4战胜对手，第二盘2-5暂时落后。 比赛开始后，双方各自完成保发，普里丹金娜6-3扳回一盘。关键的决胜盘比赛，郑钦文没有给对手任何机会，在自己发球局全部保发的情况下连续破掉对手三个发球局，最终以6-0拿下决胜盘，大比分2-1击败对手晋级美网女单正赛。"
