    "description": "新华社西藏吉隆8月28日电 浑浊的吉隆藏布汹涌翻腾，不断吞噬着岸边土石。河流之上，一根绳索连接对岸，一名消防救援人员正通过滑索溜过，只见他全身浸泡在湍急的河流中，河水不时没过头顶……这是28日吉隆泥石流受灾现场救援人员挺进核心受灾区的一幕。 28日，距离西藏吉隆泥石流灾害发生已经过去48小时。截至28日15时，灾害已造成5人遇难，558人失联。其中，外籍人员260人。 泥石流入境，通往吉隆口岸的G216最后几公里道路，被浓稠的灰褐色泥浆…",
    "content": "新华社西藏吉隆8月28日电 浑浊的吉隆藏布汹涌翻腾，不断吞噬着岸边土石。河流之上，一根绳索连接对岸，一名消防救援人员正通过滑索溜过，只见他全身浸泡在湍急的河流中，河水不时没过头顶……这是28日吉隆泥石流受灾现场救援人员挺进核心受灾区的一幕。 28日，距离西藏吉隆泥石流灾害发生已经过去48小时。截至28日15时，灾害已造成5人遇难，558人失联。其中，外籍人员260人。 泥石流入境，通往吉隆口岸的G216最后几公里道路，被浓稠的灰褐色泥浆掩埋，堆积厚重的淤泥让救援人员每迈一步都费尽全身力气，大型车辆机械仍无法进入核心…"
