    "content": "新华社北京8月28日电（记者魏弘毅）记者从水利部了解到，水利部28日晚召开相关会议，研究部署西藏日喀则市吉隆县泥石流灾害抢险救援水利支持工作。 水利部相关负责人表示，要进一步抓紧抓细抓实涉水次生灾害风险隐患排查整治，以坚决有力的举措、科学高效的方法做好抢险救援水利支持工作，严防次生灾害发生。 加强水文应急监测预警。准确掌握吉隆藏布、东林藏布、普热普强藏布、郭巴龙藏布等河流水位、流量、后续来水等情况，密切监测普热普强藏布堰塞湖和错坚河冲击坑入流、出流情况及其稳定性，科学研判溃决风险和影响范围，及时提出切实可行的应急处…"
