    "description": "中新社南京8月28日电 (记者 徐珊珊)中国工程院院士万建民领衔的研究团队28日在国际学术期刊《科学》在线发表最新研究成果，首次揭示了亚洲栽培稻与非洲栽培稻种间生殖隔离的分子机制，并找到了打破这一屏障的“钥匙”。该成果为培育超高产亚非杂交稻新品种提供了重要理论基础和种质资源。",
    "content": "中新社南京8月28日电 (记者 徐珊珊)中国工程院院士万建民领衔的研究团队28日在国际学术期刊《科学》在线发表最新研究成果，首次揭示了亚洲栽培稻与非洲栽培稻种间生殖隔离的分子机制，并找到了打破这一屏障的“钥匙”。该成果为培育超高产亚非杂交稻新品种提供了重要理论基础和种质资源。"
