    "description": "新华社北京8月28日电 题：当AI帮人决策“买单”，如何筑牢支付安全底线 新华社记者吴雨 “帮我订张机票”“帮我下单买奶茶”……只需一句语音指令，AI智能体便能辅助完成比价、下单。当前，人工智能在支付领域的应用日趋活跃，多家支付机构积极探索并推出AI支付产品。 当机器开始帮人决策“买单”，资金安全如何保障？ “要守住风险底线，并释放科技效能。”中国人民银行副行长陆磊日前在第十五届中国支付清算论坛上表示，支付行业在人工智能发展和应用过程中…",
    "content": "新华社北京8月28日电 题：当AI帮人决策“买单”，如何筑牢支付安全底线 新华社记者吴雨 “帮我订张机票”“帮我下单买奶茶”……只需一句语音指令，AI智能体便能辅助完成比价、下单。当前，人工智能在支付领域的应用日趋活跃，多家支付机构积极探索并推出AI支付产品。 当机器开始帮人决策“买单”，资金安全如何保障？ “要守住风险底线，并释放科技效能。”中国人民银行副行长陆磊日前在第十五届中国支付清算论坛上表示，支付行业在人工智能发展和应用过程中面临着诸多挑战，要以问题为导向，守好风险防控底线，将消费者权益保护作为落脚点。 …"
