    "description": "远古先民竟用四马拉车？记者从宁夏银川市贺兰山岩画管理处获悉，工作人员日前在岩画复查中发现一幅罕见的“四马拉车”岩画，这是贺兰山岩画中的首次发现，在全国岩画中也属罕见，填补了当地同类题材空白。 贺兰山岩画新发现罕见“四马拉车”题材岩画。（贺兰山岩画管理处供图） 这幅新发现的“四马拉车”岩画位于洪积扇区域的一块单体岩石上，岩石半埋地下，露出地表仅约15厘米，周边杂草丛生，极不易被发现。画面尺寸为24×20厘米，采用凿刻技法制作而成，刻痕深度…",
    "content": "远古先民竟用四马拉车？记者从宁夏银川市贺兰山岩画管理处获悉，工作人员日前在岩画复查中发现一幅罕见的“四马拉车”岩画，这是贺兰山岩画中的首次发现，在全国岩画中也属罕见，填补了当地同类题材空白。 贺兰山岩画新发现罕见“四马拉车”题材岩画。（贺兰山岩画管理处供图） 这幅新发现的“四马拉车”岩画位于洪积扇区域的一块单体岩石上，岩石半埋地下，露出地表仅约15厘米，周边杂草丛生，极不易被发现。画面尺寸为24×20厘米，采用凿刻技法制作而成，刻痕深度约1.5毫米。 根据贺兰山岩画信息档案数据统计，“马拉车”题材岩画在整个贺兰山岩…"
