    "author": "刘润芝,摄像郝杰",
    "description": "临近开学，天津轻工职业技术学院机械工程学院院长王宝龙忙碌起来，迎接新一届埃及鲁班工坊留学生的同时，他也牵挂着那些已经毕业的埃及学生们。 近年来，通过埃及鲁班工坊，越来越多的埃及青年来到天津留学深造、锤炼技能，拥抱崭新未来，王宝龙是见证者，也是参与者。在他看来，如今鲁班工坊不仅是埃及青年的“技能摇篮”，更为中埃两国搭建起教育合作、产业共融、民心相通的广阔平台。 作者：刘润芝、郝杰、赵勇思源 新华社音视频部制作",
    "content": "临近开学，天津轻工职业技术学院机械工程学院院长王宝龙忙碌起来，迎接新一届埃及鲁班工坊留学生的同时，他也牵挂着那些已经毕业的埃及学生们。 近年来，通过埃及鲁班工坊，越来越多的埃及青年来到天津留学深造、锤炼技能，拥抱崭新未来，王宝龙是见证者，也是参与者。在他看来，如今鲁班工坊不仅是埃及青年的“技能摇篮”，更为中埃两国搭建起教育合作、产业共融、民心相通的广阔平台。 作者：刘润芝、郝杰、赵勇思源 新华社音视频部制作"
