    "content": "快科技8月28日消息，乘联分会最新动力电池统计数据出炉， 1-7月，我国动力和其它电池合计产量为1287GWh，同比增长32%。 国内市场宁德时代继续保持绝对龙头地位，1-7月国内动力电池装车份额达到45.8%，几乎拿下接近一半的国内市场。 排在第二位的是比亚迪，国内份额17.7%。 两家头部企业加起来合计占比64%。 剩下36%的市场空间，分给国轩高科、中创新航、吉利耀宁、楚能新能等二线电池厂商，第二梯队的竞争越来越激烈。 现在行业有一个很有意思的现象，电池厂生产出来的电池，并不全都装到新能源汽车上面。 7月国内…"
