    "content": "目前，国产动画电影《牛来》在IMDb上的平均评分稳定在6.5分。 其中， 打满分10分的用户占比高达68.1%，而打1分的用户占比为12.2%。 不过，不同国家和地区的观众打分存在较大差异： 美国网友平均评分为6.2分，中国网友平均评分为4.6分，印度网友平均评分为7.4分，英国网友平均评分为6.9分。 据了解，目前《牛来》累计票房已突破5000万元。 此前，部分主流媒体与业内评论指出，影片过于粗糙的制作水准已触及院线动画的质量底线。 若仅凭猎奇和玩梗便能获得大量票房，或将对行业形成“劣币驱逐良币”的不良导向。 资…"
