    "content": "新华社北京8月28日电 题：证监会发文支持房地产开发企业合理融资 新华社记者刘羽佳、刘慧 8月28日，中国证监会对外发布《关于资本市场支持构建房地产发展新模式的意见》，这是资本市场涉房地产各项融资业务的指导性文件。 意见着力改革完善房地产企业股票、债券、资产支持证券（ABS）和不动产投资信托基金（REITs）等融资制度，满足房地产企业合理融资需求，助力构建房地产发展新模式。 意见中明确了一系列支持房地产开发企业合理融资的具体举措—— 强化资本市场功能发挥，支持上市房企通过定向增发、定向可转债等向特定对象发行方式再融…"
