    "content": "IT之家 8 月 28 日消息，美团今日发布 2026 财年上半年及第二财季报告。据新浪科技报道，美团 CEO 王兴在电话会议中谈及公司国际化进展：“2024 年 9 月，Keeta 在沙特市场开始试运营，到今年 7 月实现盈利，只用了 22 个月。” 据报道，Keeta 已在中国香港市场实现 UE（Unit Economics，单位经济）转正，用时 29 个月。王兴说道：“沙特是一个规模比香港更大、对我们来说非常陌生的市场， 但我们用更短的时间跑通了 UE 模型 ， 说明 Keeta 的运营模式在海外市场具备较强…"
